// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 amount, bool doReenter) public {
        amount = bound(amount, 1 ether, 1000 ether);
        ReentrantAttacker attacker = new ReentrantAttacker();
        attacker.setTarget(c);
        attacker.setReenter(doReenter);

        vm.deal(address(attacker), amount);
        vm.prank(address(attacker));
        c.deposit{value: amount}();

        bool ok;
        try attacker.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: after a full withdrawal cycle, the caller's funds leave and the
        // contract retains nothing — a completed withdrawAll never reverts for a
        // funded depositor, even against a re-entrant counterparty.
        assertTrue(ok && address(c).balance == 0 && address(attacker).balance == amount);
    }
}

contract ReentrantAttacker {
    ReentrancyDAO target;
    bool reenter;

    function setTarget(ReentrancyDAO t) external { target = t; }
    function setReenter(bool r) external { reenter = r; }

    function deposit() external payable {
        target.deposit{value: msg.value}();
    }

    function withdrawAll() external {
        target.withdrawAll();
    }

    receive() external payable {
        if (reenter) {
            reenter = false;
            target.withdrawAll();
        }
    }
}
